/**
 * PROTOTYPE. Generates a per-style-key reference page from the JSON Schema plus
 * the platform binding declarations — the shape of the autogenerated schema docs
 * the hand-written site/src/content/docs/schema/styles/*.md pages would become.
 *
 * Deliberately limited to the keys named in PROTOTYPE_KEYS. Converting all 46 is
 * a separate decision and would bake in a page design nobody has reviewed; three
 * pages is enough to judge it.
 *
 * Writes to mappings/_prototype-style-pages/ rather than over the existing
 * hand-written pages, so the two can be compared side by side.
 *
 * Usage:  node scripts/build-style-pages.mjs
 */

import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, resolve, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const pkg = resolve(here, '..');
const outDir = join(pkg, 'mappings/_prototype-style-pages');

// One key per interesting shape: a plain independent key, a cluster-resolved key,
// and one the schema describes but a platform does not realise.
const PROTOTYPE_KEYS = ['opacity', 'layoutSizingHorizontal', 'strokeDashPattern'];

const styles = JSON.parse(readFileSync(join(pkg, 'schema/styles.schema.json'), 'utf8'));
const props = styles.definitions.Styles.properties;

const bindings = Object.fromEntries(
  ['figma', 'react'].map((p) => [p, JSON.parse(readFileSync(join(pkg, `mappings/bindings/${p}.json`), 'utf8'))])
);
const defaults = JSON.parse(readFileSync(join(pkg, 'mappings/bindings/_defaults.json'), 'utf8')).defaults;

const kebab = (s) => s.replace(/[A-Z]/g, (c) => `-${c.toLowerCase()}`);

/** Resolve a $ref one level so the page can state the value type. */
const valueType = (prop) => {
  if (prop.$ref) return prop.$ref.replace(/^.*\/definitions\//, '');
  if (prop.type) return Array.isArray(prop.type) ? prop.type.join(' | ') : prop.type;
  return 'see schema';
};

mkdirSync(outDir, { recursive: true });

for (const key of PROTOTYPE_KEYS) {
  const prop = props[key];
  if (!prop) {
    console.error(`unknown style key: ${key}`);
    process.exit(1);
  }

  const def = defaults[key] ?? {};
  const assumed = def.assumed === null ? '*apply nothing*' : `\`${JSON.stringify(def.assumed)}\``;

  const platformRows = Object.entries(bindings).map(([platform, b]) => {
    const v = b.concepts.styles[key] ?? { disposition: 'unverified' };
    const realises = v.cluster
      ? `resolved jointly — cluster \`${v.cluster}\``
      : (v.target ? `\`${v.target}\`` : (v.module?.length ? v.module.map((m) => `\`${m}\``).join(', ') : '—'));
    const name = platform === 'figma' ? 'Figma' : 'React';
    const disp = v.disposition === 'unverified' ? '**unverified**' : v.disposition;
    return `| [${name}](/schema/mappings/${platform}/) | ${disp} | ${realises} | ${v.notes ?? ''} |`;
  });

  // Where a key is cluster-resolved on any platform, the page says so rather than
  // implying a per-key mapping exists.
  const clusterNotes = Object.entries(bindings).flatMap(([platform, b]) => {
    const cl = b.concepts.styles[key]?.cluster;
    if (!cl) return [];
    const c = b.concepts.styleClusters[cl];
    const name = platform === 'figma' ? 'Figma' : 'React';
    return [`**${name} — \`${cl}\`.** ${c.resolution}\n\nParticipating keys: ${c.keys.map((k) => `\`${k}\``).join(', ')}.`];
  });

  const page = `---
title: "${key}"
description: "${(prop.description ?? `The ${key} style key`).replace(/"/g, '\\"').slice(0, 300)}"
---

<!-- PROTOTYPE, generated by packages/schema/scripts/build-style-pages.mjs from
     schema/styles.schema.json + mappings/bindings/*.json. Not wired into the site. -->

${prop.description ?? ''}

## Value

| | |
|---|---|
| Type | \`${valueType(prop)}\` |
| Assumed when absent | ${assumed} |
| Default declared by | ${def.declaredBy === 'none' ? '**nothing — a consumer reading this absent is guessing**' : def.declaredBy} |

## Platform bindings

| Platform | Disposition | Realised by | Notes |
|---|---|---|---|
${platformRows.join('\n')}
${clusterNotes.length ? `\n## Joint resolution\n\nThis key does not map on its own.\n\n${clusterNotes.join('\n\n')}\n` : ''}
## See also

- [Specification §11 — platform bindings](/schema/specification/)
- [Style defaults](/schema/mappings/defaults/)
- [Styles](/schema/styles/)
`;

  writeFileSync(join(outDir, `${kebab(key)}.md`), page);
  console.log(`prototype style page: ${kebab(key)}.md`);
}

console.log(`\n${PROTOTYPE_KEYS.length} pages in mappings/_prototype-style-pages/ — compare against site/src/content/docs/schema/styles/`);
